{"output": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # The target color is the most numerous non-background color (the many
    # isolated markers); the remaining compact colored object is the stencil.
    target = max((v for v in counts if v != bg), key=lambda v: counts[v])
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (bg, target) or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx] not in (bg,target) and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append(comp)
    template=max(comps,key=len)
    r0,r1=min(r for r,c in template),max(r for r,c in template)
    c0,c1=min(c for r,c in template),max(c for r,c in template)
    anchor=((r0+r1)//2,(c0+c1)//2)
    pattern=[(r-anchor[0],c-anchor[1],grid[r][c]) for r,c in template]
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==target:
                for dr,dc,color in pattern:
                    y,x=r+dr,c+dc
                    if 0<=y<h and 0<=x<w: out[y][x]=color
    return out

if __name__=='__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))", "exit_code": 0, "error": null}

